    public static function svg(string $name, string $class = '', int $size = 20, float $stroke = 2): string
    {
        $paths = self::PATHS[$name] ?? self::PATHS['package'];
        return sprintf(
            '<svg class="icon %s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            htmlspecialchars($class, ENT_QUOTES),
            $size,
            $size,
            $stroke,
            $paths
        );
    }
}
